// Project Card Component
function ProjectCard({ project }: { project: { id: string; title: string; description: string; status: string; city: string; province: string } }) {
    return (
        <div className="p-4 bg-muted rounded-lg border border-border">
            <div className="flex items-start justify-between mb-2">
                <h4 className="font-semibold text-foreground">{project.title}</h4>
                <Badge
                    variant={project.status === 'completed' ? 'default' : project.status === 'ongoing' ? 'secondary' : 'destructive'}
                    className={
                        project.status === 'completed'
                            ? 'bg-#0D9488'
                            : project.status === 'ongoing'
                                ? 'bg-blue-500'
                                : ''
                    }
                >
                    {project.status.charAt(0).toUpperCase() + project.status.slice(1)}
                </Badge>
            </div>
            <p className="text-sm text-muted-foreground mb-2">{project.description}</p>
            <div className="flex items-center gap-1 text-xs text-muted-foreground">
                <MapPin className="h-3 w-3" />
                {project.city}, {project.province}
            </div>
        </div>
    );
}
